      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Is GST applicable on hospital services in Mumbai?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Core healthcare by clinical establishments is EXEMPT under Notification 12/2017 Sl.74 (OPD, IPD, surgeries, diagnostics by hospital). Room rent above Rs 5,000/day non-ICU attracts 5% GST without ITC. Pharmacy retail to outpatients, canteen to non-patients, and cosmetic procedures attract GST. Patron segregates exempt and taxable."
          }
        },
        {
          "@type": "Question",
          "name": "Is trust audit mandatory for charitable hospitals?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Under S.12A(1)(b), every trust with income exceeding Rs 2,50,000 (before S.11/12) must get CA audit. Form 10B (income > Rs 5 Cr or foreign) or 10BB before ITR-7 due date. Non-filing = loss of entire exemption. Plus Charity Commissioner IX-C and S.41AA bed report."
          }
        },
        {
          "@type": "Question",
          "name": "How much does healthcare accounting cost in Mumbai?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Clinic/doctor: Rs 15,000-25,000/month. Nursing home ("
          }
        },
        {
          "@type": "Question",
          "name": "Can hospitals claim ITC on medical equipment?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No - for equipment used in exempt services. Core clinical is GST-exempt so no ITC on MRI, CT, surgical equipment for exempt use. If hospital has mixed services, proportionate ITC under Rule 42/43 for taxable portion only. Embedded GST on exempt = absorbed by hospital."
          }
        },
        {
          "@type": "Question",
          "name": "Do standalone diagnostic labs need GST registration?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Labs operating independently must charge 18% GST if turnover exceeds Rs 20 lakh. Can claim ITC on reagents, equipment, operational inputs. Registration mandatory. Patron files for Mumbai labs across all 4 Commissionerate divisions."
          }
        },
        {
          "@type": "Question",
          "name": "Can healthcare providers get accounting done online?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Trust audit, Form 10B, Charity Commissioner submissions, GST returns, payroll, TDS all handled digitally. Walk-in at Marine Lines for hospital administrators from Parel, Bandra, Andheri, BKC. Document exchange via cloud."
          }
        }
      ]
    }
  ]
